insert into items (id, bundle_id, item_type, level, seed_cell_id, setting, relation, function, channel, scene_id, speaker_role, listener_role, topic, stem, correct_index, explanation_ja, explanation_en, vocab_notes, documents, dialogue, narration_clip_id, model_p_correct) values ('e30344079e', 'sougou_choukai_J3_003', 'sougou_choukai', 'J3', 'negotiation+other_department+what_changed@J3', 'negotiation', 'other_department', 'what_changed', 'in_person', 'scene_meeting_room_table', null, null, '交渉条件の一部変更報告', 'みどり物産との交渉について、前回の合意内容から何が変わりましたか。', 3, '前回は「単価3％引き下げ、納期2週間短縮」で合意していたが、今回は材料費の高騰により単価引き下げが見送りになった。一方、納期短縮の2週間については先方にとっても重要なためそのまま維持されることになった。営業部の担当者Bが「単価は引き続き下がる」と発言するが、これはAに訂正されており誤り。また4週間や3％という数字は前回や交渉前の条件であり、今回の結論をそのまま表すものではない。会話の流れを追わないと、前回の合意内容や途中の誤った発言をそのまま答えに選んでしまう。', 'The price cut is dropped due to rising material costs, but the two-week delivery shortening stays; a colleague''s incorrect guess and earlier figures are traps.', '[{"term": "単価", "reading": "たんか", "meaning": "unit price"}, {"term": "見送る", "reading": "みおくる", "meaning": "to postpone or forgo"}, {"term": "納期短縮", "reading": "のうきたんしゅく", "meaning": "shortening of the delivery deadline"}]', '[]', '[{"speaker_role": "製造部の担当者", "text": "みどり物産との件、前回は単価を3％引き下げて、納期も4週間から2週間に短縮するという話でしたよね。今回もその通りで決まったんですか。", "clip_id": "8ef8a80a9858403d"}, {"speaker_role": "営業部の担当者A", "text": "それが、先方の事情で単価の引き下げは今回見送りになりまして。", "clip_id": "2f009b15d794eeae"}, {"speaker_role": "営業部の担当者B", "text": "いえ、単価は引き続き3％下げる方向だと聞いていますけど。", "clip_id": "e3e24903830f0369"}, {"speaker_role": "営業部の担当者A", "text": "いや、さっき先方から連絡がありまして、材料費が上がっているとのことで、引き下げはなしになりました。ただ、納期短縮の2週間のほうは、そのまま進めることで合意しています。", "clip_id": "e91cdaf36c561dc5"}, {"speaker_role": "製造部の担当者", "text": "分かりました。では製造スケジュールは2週間に合わせて組みますね。", "clip_id": "a3daf37e24d2a808"}, {"speaker_role": "営業部の担当者A", "text": "お願いします。", "clip_id": "884de14daa505eb7"}]', '8bbcc26ca55109b1', 1.0) on conflict (id) do update set bundle_id = excluded.bundle_id, item_type = excluded.item_type, level = excluded.level, seed_cell_id = excluded.seed_cell_id, setting = excluded.setting, relation = excluded.relation, function = excluded.function, channel = excluded.channel, scene_id = excluded.scene_id, speaker_role = excluded.speaker_role, listener_role = excluded.listener_role, topic = excluded.topic, stem = excluded.stem, correct_index = excluded.correct_index, explanation_ja = excluded.explanation_ja, explanation_en = excluded.explanation_en, vocab_notes = excluded.vocab_notes, documents = excluded.documents, dialogue = excluded.dialogue, narration_clip_id = excluded.narration_clip_id, model_p_correct = excluded.model_p_correct;
